#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long t;
    long long cap;
    cin >> t >> cap;
    vector<vector<long long>> kinds(t, vector<long long>(2));
    for (int i = 0; i < t; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> kinds[i][j];
        }
    }

    sort(kinds.begin(), kinds.end(), [](const vector<long long>& x, const vector<long long>& y) { return x[1] > y[1]; });
    long long total = 0;
    for (const vector<long long>& kind : kinds) {
        long long take = min(kind[0], cap);
        total += take * kind[1];
        cap -= take;
        if (cap == 0) break;
    }
    cout << total << "\n";

    return 0;
}

