import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long t = Long.parseLong(next());
        long cap = Long.parseLong(next());
        long[][] kinds = new long[(int) t][2];
        for (int i = 0; i < kinds.length; i++) {
            for (int j = 0; j < kinds[i].length; j++) {
                kinds[i][j] = Long.parseLong(next());
            }
        }

        long[] keys = new long[(int) t];
        for (int i = 0; i < t; i++) keys[i] = kinds[i][1] * 100000L + i;
        Arrays.sort(keys);
        long total = 0;
        for (int p = (int) t - 1; p >= 0 && cap > 0; p--) {
            int i = (int) (keys[p] % 100000L);
            long take = Math.min(kinds[i][0], cap);
            total += take * kinds[i][1];
            cap -= take;
        }
        System.out.println(total);
    }
}
